BEGIN TRANSACTION;
CREATE TABLE pokemon_cards (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                card_name_en TEXT,
                series_name_en TEXT,
                card_number TEXT,
                UNIQUE(card_name_en, series_name_en, card_number)
            );
CREATE TABLE pokemon_names (
                number TEXT PRIMARY KEY,
                korean_name TEXT,
                english_name TEXT
            );
CREATE TABLE series_global_info (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                series_name_en TEXT,
                series_name_jp TEXT,
                series_name_us TEXT,
                release_date TEXT,
                era TEXT,
                UNIQUE(series_name_en)
            );
CREATE TABLE series_kr_info (
                series_name TEXT PRIMARY KEY,
                thumbnail_url TEXT
            );
DELETE FROM "sqlite_sequence";
COMMIT;
